from nicegui import ui

name_input = ui.input("Your name", value="")
message = ui.label("Ready")

def greet():
    name = (name_input.value or "").strip()
    if name:
        message.set_text(f"Hello {name}!")
    else:
        message.set_text("Enter your name.")

ui.button("Greet", on_click=greet)

