from nicegui import ui

ui.label("What does GUI stand for?")
answer = ui.input("Your answer", value="")
feedback = ui.label("Ready")

def check_answer():
    text = (answer.value or "").strip().lower()
    if not text:
        feedback.set_text("Enter an answer.")
    elif text == "graphical user interface":
        feedback.set_text("Correct!")
    else:
        feedback.set_text("Try again.")

ui.button("Check", on_click=check_answer)

